import Fastify from "fastify";
const app = Fastify();
app.get("/book", async () => ({ title: "Moon Trip", pages: 24 }));
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.get("/hello/:name", async request => `Hi, ${request.params.name}!`);
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.get("/search", async request => ({ term: typeof request.query.q === "string" ? request.query.q : "" }));
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.post("/books", async (request, reply) => {
 if (typeof request.body?.title !== "string") return reply.code(400).send({ error: "Title needed" });
 return reply.code(201).send({ title: request.body.title });
});
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.get("/books/:id", { schema: { params: { type: "object", required: ["id"], properties: { id: { type: "integer", minimum: 1 } } } } }, async request => ({ id: request.params.id }));
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.decorateRequest("school", "");
app.addHook("preHandler", async request => { request.school = "Oak School"; });
app.get("/", async request => request.school);
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.decorate("greet", name => `Hi, ${name}!`);
app.get("/", async () => app.greet("Ravi"));
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
await app.register(async api => { api.get("/books", async () => ["Moon Trip"]); }, { prefix: "/api" });
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.get("/book", { schema: { response: { 200: { type: "object", properties: { title: { type: "string" } } } } } }, async () => ({ title: "Moon Trip", internalNote: "draft" }));
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.setErrorHandler((error, request, reply) => reply.code(500).send({ error: "Try again later" }));
app.get("/broken", async () => { throw new Error("Practice failure"); });
await app.listen({ port: 3000, host: "127.0.0.1" });

import Fastify from "fastify";
const app = Fastify();
app.get("/score", async () => ({ score: 8 }));
const response = await app.inject({ method: "GET", url: "/score" });
console.log(response.body);
await app.close();
